const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const leipzig = ee.Geometry.Point([12.4, 51.3]);
  const region = leipzig.buffer(15000); // 15km radius around Leipzig

  // 2. Data Acquisition & Check
  // Landsat 5 for 1987
  let col1987 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(region)
    .filterDate('1987-04-01', '1987-04-30')
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const count1987 = col1987.size().getInfo();
  console.log(`1987 Images: ${count1987}`);

  if (count1987 === 0) {
    console.log('No Landsat 5 data for April 1987');
    console.log('<answer>C1</answer>');
    return;
  }

  // Landsat 8 for 2020
  let col2020 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(region)
    .filterDate('2020-04-01', '2020-04-30')
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const count2020 = col2020.size().getInfo();
  console.log(`2020 Images: ${count2020}`);

  if (count2020 === 0) {
    console.log('No Landsat 8 data for April 2020');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Calculate MNDWI for water detection
  function addMNDWI_L5(image) {
    const mndwi = image.normalizedDifference(['SR_B2', 'SR_B5']).rename('MNDWI');
    return image.addBands(mndwi);
  }

  function addMNDWI_L8(image) {
    const mndwi = image.normalizedDifference(['SR_B3', 'SR_B6']).rename('MNDWI');
    return image.addBands(mndwi);
  }

  function maskClouds_L5(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    return image.updateMask(qaMask);
  }

  function maskClouds_L8(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    return image.updateMask(qaMask);
  }

  col1987 = col1987.map(maskClouds_L5).map(addMNDWI_L5);
  col2020 = col2020.map(maskClouds_L8).map(addMNDWI_L8);

  const img1987 = col1987.median().select('MNDWI');
  const img2020 = col2020.median().select('MNDWI');

  // Water threshold: MNDWI > 0
  const water1987 = img1987.gt(0);
  const water2020 = img2020.gt(0);

  // 4. Check for valid pixels
  const validPixels1987 = water1987.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('MNDWI').getInfo();

  const validPixels2020 = water2020.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('MNDWI').getInfo();

  console.log(`Valid pixels 1987: ${validPixels1987}`);
  console.log(`Valid pixels 2020: ${validPixels2020}`);

  if (validPixels1987 === 0 || validPixels2020 === 0) {
    console.log('No valid pixels after processing');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Calculate water area
  const waterArea1987 = water1987.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('MNDWI').getInfo();

  const waterArea2020 = water2020.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('MNDWI').getInfo();

  // 6. Validation & Final Answer
  if (waterArea1987 === null || waterArea2020 === null) {
    console.log('Calculation failed');
    console.log('<answer>C3</answer>');
    return;
  }

  const area1987_km2 = waterArea1987 / 1e6;
  const area2020_km2 = waterArea2020 / 1e6;

  console.log(`Water area 1987: ${area1987_km2.toFixed(2)} km²`);
  console.log(`Water area 2020: ${area2020_km2.toFixed(2)} km²`);
  console.log(`Increase: ${(area2020_km2 - area1987_km2).toFixed(2)} km²`);

  if (area2020_km2 > area1987_km2) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
